export type BodyShape = 'streamlined' | 'round' | 'flat' | 'eel-like' | 'boxy' | 'disc' | 'torpedo';
export type Pattern = 'solid' | 'striped' | 'spotted' | 'gradient' | 'camouflage' | 'banded' | 'marbled';
export type FinType = 'small' | 'large' | 'flowing' | 'spiny' | 'none' | 'wing-like';
export type TailType = 'forked' | 'round' | 'pointed' | 'crescent' | 'whip-like' | 'square' | 'lunate';
export type SizeCategory = 'tiny' | 'small' | 'medium' | 'large' | 'huge' | 'giant';
export type SwimmingStyle = 'fast' | 'normal' | 'slow' | 'hovering' | 'bottom-dweller' | 'darting';
export type SpecialFeature = 
  | 'bioluminescent' | 'transparent' | 'armor' | 'venomous' 
  | 'electric' | 'mimic' | 'inflatable' | 'long-snout'
  | 'hammer-head' | 'saw-snout' | 'frilled' | 'angler-lure'
  | 'schooling-sync' | 'color-change' | 'gliding';

export interface CreatureVisualData {
  speciesId: number;
  bodyShape: BodyShape;
  primaryColor: string;      // HEX
  secondaryColor: string;    // HEX
  accentColor?: string;      // HEX (optional)
  pattern: Pattern;
  finType: FinType;
  tailType: TailType;
  specialFeatures: SpecialFeature[];
  sizeCategory: SizeCategory;
  swimmingStyle: SwimmingStyle;
  animationHints: string[];  // 애니메이션 키워드
  modelPriority: 1 | 2 | 3 | 4 | 5; // 1=최우선, 5=나중에
  lodDistance: { high: number; medium: number; low: number }; // LOD 전환 거리 (m)
  description: string;       // 세션 A가 참고할 형태 설명
}

