// Lookup by species ID
export const VISUAL_BY_SPECIES_ID = new Map(CREATURE_VISUALS.map(v => [v.speciesId, v]));

/**
 * Get visual data for a species, with fallback defaults
 */
export function getVisualData(speciesId: number): CreatureVisualData {
  const visual = VISUAL_BY_SPECIES_ID.get(speciesId);
  if (visual) return visual;
  
  // Fallback for missing data
  return {
    speciesId,
    bodyShape: 'streamlined',
    primaryColor: '#808080',
    secondaryColor: '#C0C0C0',
    pattern: 'solid',
    finType: 'small',
    tailType: 'forked',
    specialFeatures: [],
    sizeCategory: 'medium',
    swimmingStyle: 'normal',
    animationHints: ['tail-wag'],
    modelPriority: 5,
    lodDistance: { high: 15, medium: 35, low: 70 },
    description: '기본 물고기 모델',
  };
}

/**
 * Get species sorted by model priority (1 = highest priority)
 */
export function getSpeciesByPriority(): CreatureVisualData[] {
  return [...CREATURE_VISUALS].sort((a, b) => a.modelPriority - b.modelPriority);
}

/**
 * Get all species for a specific priority level
 */
export function getSpeciesAtPriority(priority: 1 | 2 | 3 | 4 | 5): CreatureVisualData[] {
  return CREATURE_VISUALS.filter(v => v.modelPriority === priority);
}

/**
 * Get color palette for a species (useful for procedural variation)
 */
export function getColorPalette(speciesId: number): { primary: string; secondary: string; accent?: string } {
  const visual = getVisualData(speciesId);
  return {
    primary: visual.primaryColor,
    secondary: visual.secondaryColor,
    accent: visual.accentColor,
  };
}
